'use strict';
const chapters=window.CHAPTERS;
const allSections=chapters.flatMap(c=>c.sections.map(s=>({...s,chapter:c})));
const total=allSections.length;
const storageKey='practice-atlas-progress-v1';
let completed=new Set();
let currentChapter=null;
let toastTimer;
try{const v=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(v))completed=new Set(v.filter(id=>allSections.some(s=>s.id===id)));}catch{}
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const route=(c,s='')=>'#/chapter/'+c+(s?'/'+s:'');
const originalNames=['项目实践-I-I（后端框架）','项目实践-I-II（后端框架）','项目实践-II-I（前端框架）','项目实践-II-II（前端框架）','项目实践-总体功能补充'];
const shortTitles=['后端框架 · 基础搭建','后端框架 · 接口进阶','前端框架 · 页面布局','前端框架 · 数据管理','功能补充 · 登录验证'];
const icons=['{ }','R<>','</>','↗','◎'];
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500);}
function sidebar(active){
 const pct=Math.round(completed.size/total*100);
 $('#sidebar').innerHTML=`<a href="#/" class="brand" aria-label="构建手记首页"><span class="brand-mark">&lt;/&gt;</span><span><strong>构建手记</strong><small>PROJECT PRACTICE</small></span></a>
 <a class="nav-link ${active==='home'?'active':''}" href="#/"><span>▦</span>项目概览</a>
 <a class="nav-link ${active==='contents'?'active':''}" href="#/contents"><span>≡</span>全部教程<span class="nav-status">${total}</span></a>
 <div class="nav-label">LEARNING PATH / 学习路径</div>
 ${chapters.map((c,i)=>`<a href="${route(c.id)}" class="nav-link ${active===c.id?'active':''}" ${active===c.id?'aria-current="page"':''}><span class="nav-num">${c.number}</span>${shortTitles[i]}${c.sections.every(s=>completed.has(s.id))?'<span class="nav-status">✓</span>':''}</a>`).join('')}
 <div class="nav-label">WORKSPACE / 阅读空间</div>
 <a href="#/progress" class="nav-link ${active==='progress'?'active':''}"><span>◷</span>我的阅读</a>
 <a href="#/sources" class="nav-link ${active==='sources'?'active':''}"><span>↗</span>原始文档</a>
 <div class="sidebar-bottom"><a href="#/progress" class="reading-card" style="display:block"><div class="reading-card-top"><span>我的阅读进度</span><strong>${pct}%</strong></div><div class="bar"><i style="width:${pct}%"></i></div><p>已读 ${completed.size} / ${total} 节 · 记录保存在本机</p></a><div class="edition">FULL-STACK FIELD NOTES / 2026</div></div>`;
}
function header(label){$('#breadcrumb').innerHTML=`项目实践 <span style="padding:0 8px;color:#b0b8aa">/</span><b>${esc(label)}</b>`;}
function card(c,i){return `<a class="course-card" href="${route(c.id)}"><div class="course-top"><span class="course-icon">${esc(icons[i])}</span><span class="course-num">CHAPTER ${c.number}</span></div><h3>${shortTitles[i]}</h3><p>${esc(c.subtitle)}</p><div class="course-bottom"><span>${c.sections.length} 个小节 · ${esc(c.tags[0])}</span><b aria-hidden="true">↗</b></div></a>`;}
function home(){
 currentChapter=null;sidebar('home');header('项目概览');document.title='构建手记 · 全栈项目实践';
 const next=allSections.find(s=>!completed.has(s.id))||allSections[0];
 $('#main').innerHTML=`<div class="eyebrow"><i class="dot"></i> FULL-STACK DEVELOPMENT NOTES</div>
 <section class="hero"><div><h1>从一行代码，<br>到一个<em>完整项目。</em></h1><p>记录一次全栈开发的实践旅程。<br>把后端接口、前端页面与业务功能串起来，<br>让每一步构建都有迹可循。</p><div class="hero-actions"><a class="button" href="${route(next.chapter.id,next.id)}">${completed.size?'继续阅读':'开始阅读'} <span>↗</span></a><a class="text-link" href="#/contents">浏览全部教程 <span>→</span></a></div></div>
 <div class="hero-art" aria-label="项目结构示意"><div class="code-window"><div class="window-top"><i></i><i></i><i></i><span>practice / architecture.ts</span></div><pre><span class="cm">// 从结构开始，逐步构建</span>\n<span class="kw">const</span> project = {\n  backend:  <span class="vl">'Spring Boot'</span>,\n  frontend: <span class="vl">'Vue + TypeScript'</span>,\n  database: <span class="vl">'MySQL'</span>,\n  journey:  <span class="vl">'learn → build → refine'</span>\n};</pre><div class="window-foot"><i class="dot"></i> BUILD WITH UNDERSTANDING</div></div><div class="floating-tag"><b>↗</b> 一步一步，把想法变成页面</div></div></section>
 <div class="stats"><div class="stat"><b>05</b><span>项目文档<br>串联完整路径</span></div><div class="stat"><b>${total}</b><span>教程小节<br>按步骤展开</span></div><div class="stat"><b>02</b><span>开发视角<br>前端 × 后端</span></div><div class="stat"><b>&lt;/&gt;</b><span>关键代码<br>随读随复制</span></div></div>
 <section><div class="section-heading"><div><h2>沿着这条路径，开始构建</h2><p>从基础框架出发，让页面、数据和交互逐步连接。</p></div><a href="#/contents">查看完整目录 ↗</a></div><div class="course-grid">${chapters.map(card).join('')}<div class="course-card course-guide"><div class="course-top"><span class="course-num">A NOTE TO THE READER</span><span>✳</span></div><h3>读懂一段代码，<br>再向前一步。</h3><p>每节都有操作步骤、关键片段与检查要点。遇到细节，随时回到原始文档。</p><a class="text-link" href="#/sources">查看整理说明 <span>→</span></a></div></div></section>
 <section class="architecture"><div class="section-heading"><div><h2>一次请求，如何穿过整个项目</h2><p>点击下面的环节，理解每一层的职责。</p></div><span class="muted" style="font:9px var(--mono)">REQUEST → RESPONSE</span></div><div class="flow" role="group" aria-label="请求流程"><button class="active" data-flow="0" aria-pressed="true"><span>01 / VIEW</span>Vue 页面</button><button data-flow="1" aria-pressed="false"><span>02 / HTTP</span>Axios 请求</button><button data-flow="2" aria-pressed="false"><span>03 / SERVICE</span>Spring Boot</button><button data-flow="3" aria-pressed="false"><span>04 / DATA</span>MySQL 数据</button></div><div class="flow-note" id="flow-note" role="status">用户填写条件、点击查询。Vue 管理表单、加载状态与表格，把用户操作转换成一次数据请求。</div></section>
 <div class="overview-bottom"><section class="panel"><h3>这份成果，展示什么？</h3><p>以管理员管理为项目主线，梳理框架搭建、接口设计、页面组织、数据操作与登录流程。本站展示开发知识与实践路径，代码片段用于讲解关键环节。</p><div class="tag-row">${['Spring Boot','Vue 3','MyBatis-Plus','Element Plus','Axios','MySQL'].map(t=>`<span class="tag">${t}</span>`).join('')}</div></section><section class="panel"><h3>留住每一次理解</h3><p>阅读后点击“标记本节已读”，逐步完成自己的阅读路径。记录仅保存在当前浏览器，可导出为 Markdown，方便整理个人学习笔记。</p><div class="reading-actions"><a class="button secondary" href="#/progress">查看阅读记录 →</a><button class="text-link" data-action="export">导出记录 ↗</button></div></section></div>`;
}
function sectionHTML(s,i,c){return `<section class="article-section" id="${s.id}"><div class="section-kicker">${c.number}.${String(i+1).padStart(2,'0')} / PRACTICE NOTE</div><h2>${esc(s.title)}</h2><p>${esc(s.intro)}</p><ol class="steps">${s.steps.map((t,j)=>`<li data-num="${j+1}">${esc(t)}</li>`).join('')}</ol>${s.code?`<div class="code-block"><div class="code-head"><span>${esc(s.filename)} <span class="muted">/ ${esc(s.lang)}</span></span><button class="copy-button" data-copy="${s.id}" aria-label="复制${esc(s.title)}代码">复制代码</button></div><pre><code>${esc(s.code)}</code></pre></div>`:''}${s.note?`<div class="note"><b>阅读提示</b> · ${esc(s.note)}</div>`:''}${s.checks.length?`<div class="checks"><h4>CHECKPOINT / 做完之后，检查一下</h4><ul>${s.checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<div class="section-action"><button class="done-button" data-done="${s.id}" aria-pressed="${completed.has(s.id)}">${completed.has(s.id)?'✓ 已读 · 点击撤销':'○ 标记本节已读'}</button></div></section>`;}
function chapterPage(id){const c=chapters.find(c=>c.id===id);if(!c){notFound();return;}currentChapter=c;const index=chapters.indexOf(c);sidebar(c.id);header(shortTitles[index]);document.title=shortTitles[index]+' · 构建手记';
 $('#main').innerHTML=`<div class="chapter-head"><div class="chapter-eyebrow">CHAPTER ${c.number} / ${index<2?'BACKEND':index<4?'FRONTEND':'INTEGRATION'}</div><h1>${esc(c.title)}</h1><p>${esc(c.subtitle)}</p><div class="chapter-meta">${c.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}<a class="source-link" href="${c.source}" target="_blank" rel="noopener noreferrer">阅读原始文档 ↗</a></div></div><div class="article-grid"><article class="article">${c.sections.map((s,i)=>sectionHTML(s,i,c)).join('')}<div class="chapter-nav"><a href="${index?route(chapters[index-1].id):'#/'}"><span>← ${index?'上一章':'项目概览'}</span>${index?shortTitles[index-1]:'回到学习路径'}</a><a href="${index<4?route(chapters[index+1].id):'#/progress'}"><span>${index<4?'下一章':'阅读记录'} →</span>${index<4?shortTitles[index+1]:'查看已读与待读内容'}</a></div></article><nav class="toc" aria-label="本章目录"><h3>ON THIS PAGE / 本章目录</h3>${c.sections.map((s,i)=>`<a href="${route(c.id,s.id)}">${String(i+1).padStart(2,'0')}　${esc(s.title)}</a>`).join('')}<div class="toc-tip">按原文主题重新编排。<br>示例与补充内容均已注明。<button class="print-button" data-action="print">打印本章 ↗</button></div></nav></div>`;
}
function contents(){currentChapter=null;sidebar('contents');header('全部教程');document.title='全部教程 · 构建手记';$('#main').innerHTML=`<div class="chapter-head"><div class="chapter-eyebrow">THE LEARNING PATH</div><h1>每一步，都有一个起点。</h1><p>5 个章节，${total} 个小节。可以按顺序阅读，也可以直接进入想了解的主题。</p></div>${chapters.map((c,i)=>`<section class="chapter-contents-group"><h2><span class="nav-num">${c.number}</span>　${shortTitles[i]}</h2><div class="chapter-contents">${c.sections.map(s=>`<a href="${route(c.id,s.id)}">${esc(s.title)}<span>${completed.has(s.id)?'✓ 已读':'阅读 →'}</span></a>`).join('')}</div></section>`).join('')}`;}
function sources(){currentChapter=null;sidebar('sources');header('原始文档');document.title='原始文档与整理说明 · 构建手记';$('#main').innerHTML=`<div class="chapter-head"><div class="chapter-eyebrow">SOURCES & EDITORIAL NOTES</div><h1>让每一处知识，都有来处。</h1><p>本站依据以下 5 份腾讯文档整理，原文截图、完整示例与细节可通过链接查阅。</p></div><div class="source-list">${chapters.map((c,i)=>`<div class="source-item"><span class="source-no">${c.number}</span><div><h3>${originalNames[i]}</h3><p>${esc(c.subtitle)}</p></div><a href="${c.source}" target="_blank" rel="noopener noreferrer">打开原文 ↗</a></div>`).join('')}</div><section class="panel source-notice"><h3>关于这个网站</h3><p>这是基于课程文档重新组织的教程与成果展示网站。章节介绍、步骤和检查要点经过提炼；代码区分别标注“按原文整理”“整理示例”或“补充示例”。本站不是原文逐页复刻，原始截图及未展开的实现细节请查看对应文档。</p><p>代码侧重展示关键逻辑，部分片段省略包名、导入、类型声明或配套方法，不能把单个片段当作完整可运行工程。网站本身提供阅读、搜索、复制与本地进度记录，不运行文档中的管理员系统。</p><p>技术路线按提供的文档整理，安装界面与依赖兼容性应以自己项目所用版本为准。原文中的个人信息、连接凭据及软件破解链接未收录。</p></section>`;}
function progress(){currentChapter=null;sidebar('progress');header('我的阅读');document.title='我的阅读 · 构建手记';$('#main').innerHTML=`<div class="chapter-head"><div class="chapter-eyebrow">YOUR READING JOURNEY</div><h1>已经读过的，都是积累。</h1><p>已标记 ${completed.size} / ${total} 个小节。阅读标记由你手动选择，仅记录在当前浏览器。</p><div class="reading-actions"><button class="button" data-action="export">导出阅读记录 ↗</button><button class="button secondary" data-action="reset" ${completed.size?'':'disabled'}>重置标记</button></div></div><div class="progress-grid">${chapters.map((c,i)=>`<section class="progress-item"><h3>${shortTitles[i]}</h3>${c.sections.map(s=>`<a class="${completed.has(s.id)?'complete':''}" href="${route(c.id,s.id)}"><span>${esc(s.title)}</span><span>${completed.has(s.id)?'✓ 已读':'○ 待读'}</span></a>`).join('')}</section>`).join('')}</div>`;}
function notFound(){currentChapter=null;sidebar('');header('页面未找到');document.title='页面未找到 · 构建手记';$('#main').innerHTML='<div class="chapter-head"><h1>这条阅读路径暂时不存在。</h1><p>可以回到完整目录，继续探索。</p><a class="button" href="#/contents">查看教程目录 →</a></div>';}
function closeMenu(){$('#sidebar').classList.remove('open');$('#shade').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}
function render(){let parts=location.hash.slice(1).split('/').filter(Boolean);let prior=currentChapter?.id;closeMenu();if(parts[0]==='chapter'){if(prior!==parts[1])chapterPage(parts[1]);else sidebar(parts[1]);if(parts[2]){requestAnimationFrame(()=>document.getElementById(parts[2])?.scrollIntoView({behavior:'auto'}));}else window.scrollTo({top:0,behavior:'auto'});}else{({contents,progress,sources}[parts[0]]||(parts.length?notFound:home))();window.scrollTo({top:0,behavior:'auto'});} }
function search(){const q=$('#search-input').value.trim().toLowerCase();const matches=allSections.filter(s=>!q||[s.title,s.intro,s.code,...s.steps,...s.chapter.tags].join(' ').toLowerCase().includes(q));$('#search-results').innerHTML=matches.length?matches.map(s=>`<a class="search-result" href="${route(s.chapter.id,s.id)}" data-search-result><small>CHAPTER ${s.chapter.number} / ${esc(s.chapter.tags[0])}</small><strong>${esc(s.title)}</strong><p>${esc(s.intro)}</p></a>`).join(''):`<div class="empty-state">没有找到“${esc($('#search-input').value)}”相关内容。<br>试试“分页”“登录”或“路由”。</div>`;}
function openSearch(){if(!$('#search-dialog').open)$('#search-dialog').showModal();search();$('#search-input').focus();}
function saveProgress(){try{localStorage.setItem(storageKey,JSON.stringify([...completed]));return true;}catch{toast('浏览器未允许保存，当前记录仅在本次页面保留');return false;}}
function exportProgress(){let text='# 构建手记 · 阅读记录\n\n'+`已读 ${completed.size} / ${total} 节。\n\n`;chapters.forEach((c,i)=>{text+=`## ${c.number} ${shortTitles[i]}\n\n原始文档：${c.source}\n\n`;c.sections.forEach(s=>text+=`- [${completed.has(s.id)?'x':' '}] ${s.title}\n`);text+='\n学习笔记：\n\n';});const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='构建手记-阅读记录.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('阅读记录已导出');}
const flowNotes=['用户填写条件、点击查询。Vue 管理表单、加载状态与表格，把用户操作转换成一次数据请求。','Axios 将筛选条件放进请求体，把 pageNum 与 pageSize 放进查询参数，发送到 /admin/list。','Controller 接收请求，Service 组织业务，Mapper 访问数据。统一返回类与异常处理让响应保持一致。','MySQL 保存管理员记录。查询结果经过分页包装，沿原路返回页面，最终更新列表与分页总数。'];
document.addEventListener('click',async e=>{
 const t=e.target.closest('button,a');if(!t)return;
 if(t.classList.contains('skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({behavior:'auto'});return;}
 if(t.dataset.action==='search')openSearch();
 if(t.dataset.action==='close-search')$('#search-dialog').close();
 if(t.hasAttribute('data-search-result')){$('#search-dialog').close();if(t.hash===location.hash)render();}
 if(t.dataset.action==='export')exportProgress();
 if(t.dataset.action==='print')window.print();
 if(t.dataset.action==='reset'&&confirm('清除本浏览器中的所有已读标记？此操作不会修改教程内容。')){completed.clear();saveProgress();progress();toast('已读标记已重置');}
 if(t.dataset.done){const id=t.dataset.done;completed.has(id)?completed.delete(id):completed.add(id);saveProgress();t.setAttribute('aria-pressed',String(completed.has(id)));t.textContent=completed.has(id)?'✓ 已读 · 点击撤销':'○ 标记本节已读';sidebar(currentChapter?.id||'home');}
 if(t.dataset.copy){const s=allSections.find(s=>s.id===t.dataset.copy);try{await navigator.clipboard.writeText(s.code);t.textContent='已复制 ✓';toast('代码已复制');setTimeout(()=>t.textContent='复制代码',1600);}catch{const range=document.createRange();range.selectNodeContents(t.closest('.code-block').querySelector('code'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);toast('已选中代码，请使用系统复制快捷键');}}
 if(t.dataset.flow!==undefined){document.querySelectorAll('[data-flow]').forEach(b=>{b.classList.toggle('active',b===t);b.setAttribute('aria-pressed',String(b===t));});$('#flow-note').textContent=flowNotes[Number(t.dataset.flow)];}
 if(t.id==='menu-toggle'){const open=$('#sidebar').classList.toggle('open');$('#shade').classList.toggle('open',open);t.setAttribute('aria-expanded',String(open));}
 if(t.closest('#sidebar')&&t.tagName==='A')closeMenu();
});
$('#shade').addEventListener('click',closeMenu);
$('#search-input').addEventListener('input',search);
$('#search-dialog').addEventListener('click',e=>{if(e.target===$('#search-dialog'))$('#search-dialog').close();});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape')closeMenu();});
window.addEventListener('hashchange',render);
window.addEventListener('storage',e=>{if(e.key===storageKey){try{const v=JSON.parse(e.newValue||'[]');if(!Array.isArray(v))return;completed=new Set(v.filter(id=>allSections.some(s=>s.id===id)));currentChapter=null;render();}catch{}}});
render();
